// <auto-generated/>
using Shared.DTO.Departments;
using Shared.DTO.Pivot;
using Shared.DTO.Product;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.Product
{
    public partial class Create
    {
        private ProductDto product = new();

        private List<DepartmentProductDto> departmentStocks = new();

        private bool isSaving;
        private string? errorMessage;
        private string? loadError;

        protected override async Task OnInitializedAsync()
        {
            try
            {
                var departments =
                    await Http.GetFromJsonAsync<List<DepartmentDto>>(
                        "api/Departments") ?? new();

                departmentStocks = departments
                    .Select(d => new DepartmentProductDto
                    {
                        DepartmentUuid = d.Uuid,
                        DepartmentName = d.Name,
                        Total = 0
                    })
                    .ToList();
            }
            catch (Exception ex)
            {
                loadError = $"Could not load departments: {ex.Message}";
            }
        }

        private async Task CreateProduct()
        {
            if (isSaving)
                return;

            errorMessage = null;

            var selectedStocks = departmentStocks
                .Where(item => item.Selected)
                .ToList();

            if (selectedStocks.Any(item => item.Total < 0))
            {
                errorMessage = "Department stock totals cannot be negative.";
                return;
            }

            product.DepartmentProducts = selectedStocks
                .Select(item => new DepartmentProductDto
                {
                    DepartmentUuid = item.DepartmentUuid,
                    Total = item.Total
                })
                .ToList();

            try
            {
                isSaving = true;

                var response = await Http.PostAsJsonAsync(
                    "api/Products",
                    product);

                if (response.IsSuccessStatusCode)
                {
                    NavMan.NavigateTo("/Product");
                }
                else
                {
                    var responseMessage =
                        await response.Content.ReadAsStringAsync();

                    errorMessage = string.IsNullOrWhiteSpace(responseMessage)
                        ? $"Could not create product. Status: {(int)response.StatusCode}"
                        : responseMessage;
                }
            }
            catch (Exception ex)
            {
                errorMessage = $"An error occurred while creating the product: {ex.Message}";
            }
            finally
            {
                isSaving = false;
            }
        }
    }
}
